<?php
namespace App\Services;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Http\Controllers\{CcsAdminController,CcsBillingController};
class CcsWalkInSale{
public function save(Request $r){$rules=app(CcsHumanRules::class);abort_unless(($r->user()->ccs_active??false)&&in_array(app(CcsAdministration::class)->role($r->user()),['owner','cashier'],true),403);$r->validate(['initial_request_token'=>'required|uuid','initial_received'=>'required|numeric|min:0|decimal:0,2','description'=>'required|array|min:1|max:20','quantity'=>'required|array','unit_price'=>'required|array','discount'=>'nullable|numeric|min:0|decimal:0,2']);$token=$r->input('initial_request_token');
$prior=DB::table('invoices')->where('rules_request_token',$token)->first();if($prior){if(!$prior->rules_payload_hash||!hash_equals($prior->rules_payload_hash,$this->hash($r)))$rules->fail('rules','Walk-in token already used for different details.');return redirect()->route('ccs.invoices.show',$prior->id);}
$approval=null;if((float)$r->input('discount',0)>0)$approval=$rules->approve($r,'walk_in_discount',['description'=>$r->input('description'),'quantity'=>$r->input('quantity'),'unit_price'=>$r->input('unit_price'),'parts'=>$r->input('inventory_item_id',[]),'discount'=>number_format((float)$r->input('discount'),2,'.','')]);
return DB::transaction(function()use($r,$rules,$approval,$token){$rules->lock();$prior=DB::table('invoices')->where('rules_request_token',$token)->first();if($prior){if(!hash_equals((string)$prior->rules_payload_hash,$this->hash($r)))$rules->fail('rules','Request token was reused for different details.');return redirect()->route('ccs.invoices.show',$prior->id);}
foreach($r->input('description') as $i=>$desc){if(!empty($r->input('requires_serial',[])[$i])||!empty($r->input('is_battery_module',[])[$i])||trim((string)($r->input('manual_serial',[])[$i]??''))!==''||!empty($r->input('stock_unit_id',[])[$i])||!empty($r->input('expected_warranty_rule_id',[])[$i]))$rules->fail('rules','Walk-in is only for nonserialized items without warranty. Select a customer/vehicle for this item.');$partId=$r->input('inventory_item_id',[])[$i]??null;if($partId){$part=DB::table('inventory_items')->find($partId);if(!$part||!$part->active||$part->has_serial||$part->serial_on_sale||$part->is_battery_module||$part->default_warranty_rule_id)$rules->fail('rules','Walk-in part is serialized, warranty-covered or inactive. Use a customer sale.');}}
if($r->boolean('is_credit_sale'))$rules->fail('rules','Walk-in cannot be a credit sale.');$sum=0;foreach($r->input('quantity') as $i=>$q)$sum+=round((float)$q*(float)($r->input('unit_price')[$i]??0),2);$total=round($sum-(float)$r->input('discount',0),2);if($total<0||(int)round((float)$r->input('initial_received')*100)<(int)round($total*100))$rules->fail('initial_received','Walk-in must be paid in full.');
$customer=DB::table('customers')->where('customer_code','CCS-WALKIN')->first();if(!$customer){$cid=DB::table('customers')->insertGetId(['customer_code'=>'CCS-WALKIN','name'=>'Walk-in counter sales (system)','is_system_walkin'=>true,'created_at'=>now(),'updated_at'=>now()]);}else{$cid=$customer->id;if(!$customer->is_system_walkin)$rules->fail('rules','Reserved walk-in customer code is in use.');}
$vehicle=DB::table('vehicles')->where('vehicle_code','CCS-WALKIN')->first();if(!$vehicle)$vid=DB::table('vehicles')->insertGetId(['customer_id'=>$cid,'vehicle_code'=>'CCS-WALKIN','registration_number'=>'WALK-IN','make'=>'Counter sale','model'=>'No vehicle required','is_system_walkin'=>true,'plate_kind'=>'system','created_at'=>now(),'updated_at'=>now()]);else{$vid=$vehicle->id;if(!$vehicle->is_system_walkin)$rules->fail('rules','Reserved walk-in vehicle code is in use.');}
$job=DB::table('repair_jobs')->insertGetId(['vehicle_id'=>$vid,'job_number'=>'PENDING-'.\Illuminate\Support\Str::uuid(),'status'=>'completed','complaint'=>'Walk-in counter sale','diagnosis'=>'No vehicle service','job_category'=>'parts_other','service_type'=>'Walk-in sale','is_system_walkin'=>true,'received_at'=>now(),'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('repair_jobs')->where('id',$job)->update(['job_number'=>sprintf('CCS-WALK-%06d',$job)]);$hash=$this->hash($r);$r->merge(['repair_job_id'=>$job]);$r->attributes->set('rules_walkin_hash',$hash);$r->attributes->set('rules_discount_authorized_by',$approval?DB::table('ccs_rule_approvals')->where('id',$approval)->value('decided_by'):(app(CcsHumanRules::class)->owner($r->user())?$r->user()->id:null));$response=app(CcsAdminController::class)->createInvoice($r);$invoice=DB::table('invoices')->where('repair_job_id',$job)->first();if(!$invoice)$rules->fail('rules','Walk-in invoice could not be created.');
$r->merge(['confirmation'=>1,'amount_received'=>$r->input('initial_received'),'method'=>$r->input('initial_method','cash'),'reference'=>$r->input('initial_reference'),'request_token'=>$token]);$response=app(CcsBillingController::class)->issue($r,$invoice->id);$rules->consume($approval,$r->user()->id);app(CcsAdministration::class)->audit($r->user()->id,'walk_in_sale_completed','invoice',$invoice->id);return $response;
},3);
}
public function hash(Request $r):string{$keys=['description','quantity','unit_price','inventory_item_id','discount','initial_received','initial_method','initial_reference'];return hash('sha256',json_encode($r->only($keys),JSON_UNESCAPED_UNICODE));}
}
